var BANK=window.__MOT_BANK||{name:"",number:"",owner:"",qr:""};
document.getElementById("bName").textContent=BANK.name;
document.getElementById("bNum").textContent=BANK.number;
document.getElementById("bOwner").textContent=BANK.owner;
var qr=document.getElementById("qr"),file=document.getElementById("file");
function showQR(s){qr.innerHTML="";var i=new Image();i.src=s;i.alt="Mã QR chuyển khoản";qr.appendChild(i);qr.style.borderStyle="solid"}
if(BANK.qr)showQR(BANK.qr);
qr.onclick=function(){var i=qr.querySelector("img");if(!i)return;var o=document.createElement("div");o.style.cssText="position:fixed;inset:0;z-index:99;background:rgba(0,0,0,.65);display:grid;place-items:center;padding:16px;cursor:zoom-out";var z=new Image();z.src=i.src;z.alt="Mã QR chuyển khoản (phóng to)";z.style.cssText="max-width:min(420px,100%);max-height:92vh;border-radius:14px;background:#fff";o.appendChild(z);o.onclick=function(){o.remove()};document.body.appendChild(o)};
qr.onkeydown=function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();qr.onclick()}};
file.onchange=function(){var f=file.files[0];if(!f)return;var r=new FileReader();r.onload=function(){showQR(r.result);try{localStorage.setItem("qr",r.result)}catch(e){}};r.readAsDataURL(f)};
document.getElementById("copy").onclick=function(){var b=this;function ok(){b.textContent="Đã sao chép";setTimeout(function(){b.textContent="Sao chép số tài khoản"},1800)}
try{navigator.clipboard.writeText(BANK.number).then(ok,ok)}catch(e){ok()}};
