var hsSet=0,hsPy=true,hsVi=true,hsT=0;
function renderHskk(){var bar=document.getElementById("hsBar"),g=document.getElementById("hsGrid");
bar.innerHTML=[0,1,2,3,4].map(function(i){return '<button type="button" class="hs-set'+(hsSet===i?' on':'')+'" data-s="'+i+'">Bộ '+(i+1)+'<small>câu '+(i*5+1)+'–'+(i*5+5)+'</small></button>'}).join("")+'<span class="hs-tg"><button type="button" data-t="py" class="'+(hsPy?'on':'')+'">Pinyin</button><button type="button" data-t="vi" class="'+(hsVi?'on':'')+'">Tiếng Việt</button></span>';
g.className="hs-g hs-bd"+(hsPy?" py":"")+(hsVi?" vi":"");
g.innerHTML=HKP.slice(hsSet*5,hsSet*5+5).map(function(p,j){var n=hsSet*5+j+1;return '<article class="hs-c" data-n="'+n+'" style="animation-delay:'+j*.07+'s"><div class="hs-im"><img src="hskk/p'+(n<10?'0':'')+n+'.jpg" alt="Tranh số '+n+'" loading="lazy" decoding="async"><span class="hs-no">'+n+'</span><span class="hs-tm" aria-hidden="true"><svg viewBox="0 0 46 46"><circle class="bg" cx="23" cy="23" r="18"/><circle class="fg" cx="23" cy="23" r="18"/></svg><b>15</b></span></div><div class="hs-b"><p class="hs-q">Nhìn tranh và nói về nội dung bức tranh (15 giây).</p><div class="hs-ans"><p class="hs-zh">'+p[0]+'</p><p class="hs-py">'+p[1]+'</p><p class="hs-vi">'+p[2]+'</p></div><div class="hs-ac"><button type="button" class="go" data-a="go">🎤 Bắt đầu nói</button><button type="button" class="sh" data-a="sh">👁 Xem bài mẫu</button><button type="button" class="ls" data-a="ls">🔊 Nghe</button></div></div></article>'}).join("")}
function hsStop(){clearInterval(hsT);[].forEach.call(document.querySelectorAll(".hs-c.run"),function(c){c.classList.remove("run");c.querySelector(".hs-tm b").textContent="15";var b=c.querySelector('[data-a="go"]');if(b)b.textContent="🎤 Bắt đầu nói"})}
document.getElementById("v-hskk").addEventListener("click",function(e){var b=e.target.closest("button");if(!b)return;
if(b.dataset.s!=null){hsStop();hsSet=+b.dataset.s;renderHskk();return}
if(b.dataset.t){if(b.dataset.t==="py")hsPy=!hsPy;else hsVi=!hsVi;renderHskk();return}
var c=b.closest(".hs-c");if(!c)return;var n=+c.dataset.n,a=b.dataset.a;
if(a==="sh"){c.classList.toggle("open");b.textContent=c.classList.contains("open")?"🙈 Ẩn bài mẫu":"👁 Xem bài mẫu"}
else if(a==="ls")say(HKP[n-1][0],.8);
else if(a==="go"){if(c.classList.contains("run")){hsStop();return}hsStop();var left=15,tb=c.querySelector(".hs-tm b");void c.offsetWidth;c.classList.add("run");b.textContent="⏹ Dừng";hsT=setInterval(function(){left--;tb.textContent=left;if(left<=0){hsStop();toast("Hết 15 giây! Bấm “Xem bài mẫu” để đối chiếu.")}},1000)}
});
