var TM={"ā":"a1","á":"a2","ǎ":"a3","à":"a4","ē":"e1","é":"e2","ě":"e3","è":"e4","ī":"i1","í":"i2","ǐ":"i3","ì":"i4","ō":"o1","ó":"o2","ǒ":"o3","ò":"o4","ū":"u1","ú":"u2","ǔ":"u3","ù":"u4","ǖ":"v1","ǘ":"v2","ǚ":"v3","ǜ":"v4","ü":"v0"};
function pyN(s){s=(s||"").normalize("NFC").toLowerCase().replace(/u:/g,"v");var l="",t="";for(var i=0;i<s.length;i++){var c=s.charAt(i),m=TM[c];if(m){l+=m.charAt(0);if(m.charAt(1)!=="0")t+=m.charAt(1)}else if(c>="a"&&c<="z")l+=c;else if(c>="1"&&c<="4")t+=c}return{l:l.replace(/v/g,"u"),t:t}}
