function key(a,b){var v=SHD[a].v[b];return v&&v.id?v.id:a+"-"+b}
function st(a,b){return P[key(a,b)]||(P[key(a,b)]={s:[0,0,0,0],r:0,n:""})}
function done(a,b){var p=P[key(a,b)];return !!p&&p.s.every(Boolean)}
function started(a,b){var p=P[key(a,b)];return !!p&&(p.s.some(Boolean)||p.r>0)}
